INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", 3001, 3001100, 2.1, 1, 2, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", -416.5, "ヤマト", 0.0, "2030/01/01 14:59:59", 100, 130011);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", 3001, 3001101, 5.68, 4, 2, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", -416.5, "ヤマト", 0.0, "2030/01/01 14:59:59", 101, 130011);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", 3001, 3001102, 0.0, 1, 1, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", -416.5, "ヤマト", 0.0, "2030/01/01 14:59:59", 102, 130011);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", 3002, 3002100, 0.0, 1, 1, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", -416.5, "フブキ", 0.0, "2030/01/01 14:59:59", 100, 130211);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", 3002, 3002101, 0.0, 1, 1, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", -416.5, "フブキ", 0.0, "2030/01/01 14:59:59", 101, 130211);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", 3002, 3002102, 8.53, 5, 2, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", -416.5, "フブキ", 0.0, "2030/01/01 14:59:59", 102, 130211);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", 3002, 3002103, 5.67, 7, 1, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", -416.5, "フブキ", 0.0, "2030/01/01 14:59:59", 103, 130211);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", 3002, 3002104, 0.0, 1, 1, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", -416.5, "フブキ", 0.0, "2030/01/01 14:59:59", 104, 130211);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", 3004, 3002300, 0.0, 3, 3, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", -416.5, "フブキ", 0.0, "2030/01/01 14:59:59", 300, 130211);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", 3005, 3002400, 0.0, 7, 7, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", -416.5, "フブキ", 0.0, "2030/01/01 14:59:59", 301, 130211);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", 3003, 3003200, 4.4, 2, 1, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", -416.5, "フブキ", 0.0, "2030/01/01 14:59:59", 200, 130211);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", 3003, 3003201, 0.0, 7, 7, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", -416.5, "フブキ", 0.0, "2030/01/01 14:59:59", 201, 130211);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", 3003, 3003202, 5.6, 1, 2, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", -416.5, "フブキ", 0.0, "2030/01/01 14:59:59", 202, 130211);
